"use client";
import { useRipple } from "@/shared/lib/useRipple";
import type { IButton } from "./button.types";
import { button } from "./button.variants";

export const Button = ({
  children,
  className,
  type = "button",
  variant = "default",
  size,
  disabled,
  ...rest
}: IButton) => {
  const { start, onAnimationEnd, RippleEffect, ripples } = useRipple();
  const styles = button({ variant, size, disabled, className });
  const rippleCondition = variant === "default" || variant === "secondary";

  return (
    <button
      disabled={disabled}
      className={styles}
      type={type}
      onMouseDown={rippleCondition ? start : undefined}
      {...rest}
    >
      {rippleCondition && (
        <RippleEffect ripples={ripples} onAnimationEnd={onAnimationEnd} />
      )}
      {children}
    </button>
  );
};

import type { ComponentProps, PropsWithChildren } from "react";
import type { ButtonVariants } from "./button.variants";

type ButtonBase = PropsWithChildren<ComponentProps<"button">>;

export interface IButton extends ButtonBase, ButtonVariants {}

import { tv, type VariantProps } from "tailwind-variants";

/**
 * Стили для Button компонента
 */
export const button = tv({
  base: [
    "relative overflow-hidden",
    "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md",
    "text-sm font-medium transition-all shrink-0 outline-none",
    "[&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 [&_svg]:shrink-0",
    "focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px]",
    "aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  ],
  variants: {
    variant: {
      default: "bg-primary text-primary-foreground hover:bg-primary/90",
      destructive: [
        "bg-destructive text-white hover:bg-destructive/90",
        "focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
      ],
      outline: [
        "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground",
        "dark:bg-input/30 dark:border-input dark:hover:bg-input/50",
      ],
      secondary: "bg-secondary text-secondary-foreground hover:bg-secondary/80",
      ghost:
        "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
      link: "text-primary underline-offset-4 hover:underline",
    },
    size: {
      default: "h-9 px-4 py-2 has-[>svg]:px-3",
      xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
      sm: "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
      lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
      icon: "size-9",
      "icon-xs": "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
      "icon-sm": "size-8",
      "icon-lg": "size-10",
    },
    disabled: {
      true: "opacity-50 pointer-events-none select-none",
      false: "",
    },
  },
  defaultVariants: {
    variant: "default",
    size: "default",
    disabled: false,
  },
});

export type ButtonVariants = VariantProps<typeof button>;

import type { MouseEvent } from "react";
import { memo, useCallback, useState } from "react";

type TRipple = {
  x: number;
  y: number;
  id: number;
  diameter: number;
};

const RippleEffect = memo(
  ({
    ripples,
    onAnimationEnd,
  }: {
    ripples: TRipple[];
    onAnimationEnd: (id: number) => void;
  }) => (
    <>
      {ripples.map(({ diameter, id, x, y }) => (
        <span
          key={id}
          style={{
            width: diameter,
            height: diameter,
            left: x,
            top: y,
            transform: "scale(0)",
            opacity: 0.5,
          }}
          onAnimationEnd={() => onAnimationEnd(id)}
          className="absolute rounded-full bg-white/75 animate-ripple pointer-events-none"
        />
      ))}
    </>
  ),
);

export const useRipple = () => {
  const [ripples, setRipples] = useState<TRipple[]>([]);

  const start = (e: MouseEvent<HTMLElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const diameter = Math.max(rect.width, rect.height) * 2;
    const x = e.clientX - rect.left - diameter / 2;
    const y = e.clientY - rect.top - diameter / 2;

    const newRipple: TRipple = {
      id: Date.now() + Math.random(),
      x,
      y,
      diameter,
    };

    setRipples((prev) => [...prev, newRipple]);
  };

  const onAnimationEnd = useCallback((id: number) => {
    setRipples((prev) => prev.filter((ripple) => ripple.id !== id));
  }, []);

  return { start, ripples, onAnimationEnd, RippleEffect };
};
